    public static final String EDITOR_CLOSE_BRACES = "editor_close_braces";
    public static final String EDITOR_ESCAPE_STRINGS = "editor_escape_strings";

    public static void initializeDefaults(IPreferenceStore store) {
        store.setDefault(PreferenceConstants.EDITOR_CLOSE_BRACES, true);
        store.setDefault(PreferenceConstants.EDITOR_ESCAPE_STRINGS, false); // Matched line
    }
}

